using Microsoft.EntityFrameworkCore;

// Cosmos DB provider context — migrated to EF Core 9.
// Three breaking changes addressed for existing documents:
// 1. Discriminator property renamed from "Discriminator" to "$type" — preserve old name
// 2. id property no longer embeds discriminator — preserve old format
// 3. Sync I/O now throws — all queries must use async methods

class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "AppDatabase");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Session>(entity =>
        {
            entity.ToContainer("Sessions");

            // EF Core 9 breaking change: default discriminator renamed to "$type".
            // Existing documents use "Discriminator" — preserve that name.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 breaking change: id format no longer includes discriminator.
            // Existing documents have "Session|<key>" format — preserve it.
            entity.HasRootDiscriminatorInJsonId(true);
        });
    }
}

class Session
{
    public string Id { get; set; } = null!;
    public string Title { get; set; } = null!;
    public DateTime StartedAt { get; set; }
}

// EF Core 9 breaking change: Cosmos DB sync I/O now throws.
// All queries must use async equivalents.
class CosmosQueryService
{
    private readonly CosmosDbContext _db;
    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // BEFORE (EF Core 8 — now throws in EF Core 9):
    //   var sessions = _db.Sessions.Where(s => s.StartedAt > cutoff).ToList();
    //   _db.SaveChanges();

    // AFTER (EF Core 9 — use async methods):
    public async Task<List<Session>> GetRecentSessionsAsync(DateTime cutoff)
    {
        return await _db.Sessions
            .Where(s => s.StartedAt > cutoff)
            .ToListAsync();
    }

    public async Task SaveAsync()
    {
        await _db.SaveChangesAsync();
    }
}

